use vstd::prelude::*;
use vstd::slice::*;

verus! {

spec fn all_same(s: Seq<char>) -> bool {
    if s.len() <= 1 {
        true
    } else {
        forall|i: int, j: int| 0 <= i < s.len() && 0 <= j < s.len() ==> s[i] == s[j]
    }
}

fn all_characters_same(char_arr: &Vec<char>) -> (result: bool)
    ensures
        result == all_same(char_arr@),
{
    // Handle empty or single-element vectors (vacuously true)
    if char_arr.len() <= 1 {
        return true;
    }
    
    // Get the first character to compare against
    let first_char = char_arr[0];
    
    // Check all remaining characters
    let slice = &char_arr[1..];
    let mut idx: usize = 0;
    
    while idx < slice.len()
        invariant
            0 <= idx <= slice.len(),
            // All characters checked so far are equal to first_char
            forall|i: int| 0 <= i < idx ==> slice[i] == first_char,
            // The slice is a valid suffix of the original vector
            slice@ == char_arr@.subrange(1, char_arr@.len() as int),
    {
        let c = slice[idx];
        if c != first_char {
            return false;
        }
        idx = idx + 1;
    }
    
    true
}

}
